package estate.svc;

import org.junit.jupiter.api.Test;

import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

class MainTest {
    @Test
    void scoreFallsAsTheRequestGrows() throws Exception {
        Main m = new Main();
        assertEquals("900", m.handle("score", Map.of("income", "1000", "amount", "100")).get("score"));
        assertEquals("500", m.handle("score", Map.of("income", "1000", "amount", "500")).get("score"));
        assertEquals("0", m.handle("score", Map.of("income", "1000", "amount", "5000")).get("score"));
    }

    @Test
    void scoreIsClampedAndUsesIntegerArithmetic() throws Exception {
        Main m = new Main();
        assertEquals("1000", m.handle("score", Map.of("income", "1000", "amount", "0")).get("score"));
        assertEquals("667", m.handle("score", Map.of("income", "3", "amount", "1")).get("score"));
        assertEquals("0", m.handle("score", Map.of("income", "1000", "amount", "1001")).get("score"));
    }

    @Test
    void scoreDoesNotOverflowForLargeInputs() throws Exception {
        Main m = new Main();
        assertEquals("500", m.handle("score", Map.of(
                "income", String.valueOf(Long.MAX_VALUE),
                "amount", String.valueOf(Long.MAX_VALUE / 2 + 1))).get("score"));
    }

    @Test
    void healthIsUp() throws Exception {
        assertEquals("UP", new Main().handle("health", Map.of()).get("status"));
    }
}
